<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;use App\Services\ProjectionSettingsService;use App\Services\ProjectionLayoutService;use App\Services\CountryFlagService;use App\Services\JudgeDirectoryService;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$type=(string)($_GET['type']??'scoring');$displayToken=trim((string)($_GET['display_token']??''));$publicSession=$displayToken!==''?LiveDisplaySessionService::byToken($pdo,$displayToken):null;if($publicSession){if($publicSession['data_mode']!=='real'||(int)($publicSession['current_round_id']??0)!==$roundId||(string)$publicSession['screen_type']!==$type){http_response_code(403);exit('Projection state changed.');}if(in_array($type,['results','winners'],true)&&empty($publicSession['results_unlocked'])){http_response_code(403);exit('Results reveal is locked.');}}else{Auth::requireAdmin();}JudgeDirectoryService::ensure($pdo);$place=(string)($_GET['place']??'');$page=max(1,(int)($_GET['page']??1));$s=$pdo->prepare("SELECT r.*,e.name event_name,e.event_date FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id");$s->execute(['id'=>$roundId]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Round not found.');}if($publicSession&&(int)$publicSession['event_id']!==(int)$r['event_id']){http_response_code(403);exit('Invalid event projection.');}$settings=ProjectionSettingsService::get($pdo,$roundId,false);$format=(string)($_GET['format']??$settings['screen_format']);$density=(string)($_GET['density']??$settings['density']);$width=(int)($_GET['width']??$settings['custom_width']??0);$height=(int)($_GET['height']??$settings['custom_height']??0);$items=[];$title='';if($type==='judges'){$title='JUDGES';JudgeDirectoryService::backfillAssignments($pdo);$s=$pdo->prepare("SELECT sj.judge_name,sj.judge_order,sj.is_chief,sj.scoring_scope,j.full_name,j.country,j.country_code,j.photo_url FROM bdc_scoring_judges sj LEFT JOIN bdc_judges j ON j.id=sj.judge_id WHERE sj.round_id=:r ORDER BY sj.judge_order");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif($type==='competitors'){$title='COMPETITORS';$s=$pdo->prepare("SELECT se.display_name,se.bib_number,se.dance_role,c.country,c.photo_url FROM bdc_scoring_entries se LEFT JOIN bdc_competitors c ON c.id=se.competitor_id WHERE se.round_id=:r AND se.entry_status='active' ORDER BY se.dance_role,se.bib_number IS NULL,se.bib_number,se.display_name");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['callbacks','finalists'],true)){$title=$type==='callbacks'?'CALLBACKS':'FINALISTS';$s=$pdo->prepare("SELECT se.display_name,se.bib_number,se.dance_role,c.country,c.photo_url,sr.rank_number FROM bdc_scoring_results sr JOIN bdc_scoring_entries se ON se.id=sr.entry_id LEFT JOIN bdc_competitors c ON c.id=se.competitor_id WHERE sr.round_id=:r AND sr.result_status IN('callback','alternate') ORDER BY sr.rank_number,se.display_name");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['winners','results'],true)){$title=$type==='winners'?'WINNER PODIUM':'FINAL RANKING';$s=$pdo->prepare("SELECT fr.final_rank,le.display_name leader_name,fe.display_name follower_name,lc.country leader_country,lc.photo_url leader_photo,fc.country follower_country,fc.photo_url follower_photo FROM bdc_scoring_final_results fr JOIN bdc_scoring_final_pairs fp ON fp.id=fr.pair_id JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id LEFT JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id LEFT JOIN bdc_competitors lc ON lc.id=le.competitor_id LEFT JOIN bdc_competitors fc ON fc.id=fe.competitor_id WHERE fr.round_id=:r AND fr.final_rank BETWEEN 1 AND 5 ORDER BY fr.final_rank ASC");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();if($type==='winners'&&$place!==''&&$place!=='all'){$reveal=max(1,min(5,(int)$place));$items=array_values(array_filter($items,fn($x)=>(int)$x['final_rank']>=$reveal));}}else{$title='SCORING IN PROGRESS';$s=$pdo->prepare("SELECT COUNT(*) total,SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted FROM bdc_scoring_judges j LEFT JOIN bdc_scoring_judge_sessions s ON s.judge_id=j.id WHERE j.round_id=:r");$s->execute(['r'=>$roundId]);$items=[$s->fetch()?:['total'=>0,'submitted'=>0]];}$animalPlaceholders=[url('public/assets/img/projection-animals/rabbit.png'),url('public/assets/img/projection-animals/baby-elephant.png'),url('public/assets/img/projection-animals/panda.png')];$layout=ProjectionLayoutService::resolve($format,max(1,count($items)),$density,$width?:null,$height?:null);$ratio=$layout['ratio'];$cols=$layout['columns'];if(in_array($type,['competitors','callbacks','finalists'],true)&&count($items)>$layout['capacity'])$items=array_slice($items,($page-1)*$layout['capacity'],$layout['capacity']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#000;color:#fff;font-family:Arial,sans-serif;overflow:hidden}.viewport{width:100vw;height:100vh;display:flex;align-items:center;justify-content:center}.stage{aspect-ratio:<?=e((string)$ratio)?>;width:min(100vw,calc(100vh * <?=e((string)$ratio)?>));height:min(100vh,calc(100vw / <?=e((string)$ratio)?>));background:radial-gradient(circle at top,#4a101e,#111827 50%,#030509);padding:2.2%;text-align:center;overflow:hidden;display:flex;flex-direction:column}.event{font-size:clamp(18px,1.8vw,46px);font-weight:900}.meta{font-size:clamp(12px,.95vw,24px);color:#ffb7c3}.title{font-size:clamp(22px,2.2vw,54px);font-weight:900;margin:1% 0}.list{flex:1;display:grid;grid-template-columns:repeat(<?=$cols?>,minmax(0,1fr));grid-auto-rows:minmax(0,1fr);gap:.7%;min-height:0}.item{background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.2);border-radius:10px;padding:3%;display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;overflow:hidden;font-size:clamp(11px,1.2vw,28px)}.photo{width:min(8vw,11vh);height:min(8vw,11vh);border-radius:50%;object-fit:cover;margin-bottom:.4em;background:transparent}.name{font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}.big{font-size:clamp(60px,10vw,220px);font-weight:900}.small{font-size:.72em;color:#cbd5e1}.podium{flex:1;display:flex;align-items:flex-end;justify-content:center;gap:1%;min-height:0}.podium-slot{width:18%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%}.podium-person{min-height:26%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;margin-bottom:2%;width:100%}.podium-photos{display:flex;justify-content:center;gap:.3vw;min-height:min(7vw,10vh)}.podium-photos img{width:min(6vw,9vh);height:min(6vw,9vh);border-radius:50%;object-fit:cover}.podium-name{font-weight:900;font-size:clamp(11px,1.15vw,27px);max-width:100%}.podium-country{font-size:clamp(9px,.75vw,18px);color:#ddd}.block{width:100%;border-radius:12px 12px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:8%;font-size:clamp(30px,5vw,100px);font-weight:900;background:linear-gradient(#7d2638,#35101a);border:2px solid rgba(255,255,255,.18)}.p1{height:58%;background:linear-gradient(#d8aa37,#6e4d00)}.p2{height:46%;background:linear-gradient(#aeb5bf,#505866)}.p3{height:38%;background:linear-gradient(#a86c45,#56311d)}.p4{height:29%}.p5{height:23%}</style></head><body><div class="viewport"><div class="stage"><div class="event"><?=e($r['event_name'])?></div><div class="meta"><?=e(strtoupper(str_replace('_',' ',$r['division'])))?> · <?=e(strtoupper($r['round_type']))?> · <?=e(!empty($r['scheduled_at'])?date('d M Y, g:i A',strtotime((string)$r['scheduled_at'])):($r['event_date']?date('d M Y',strtotime((string)$r['event_date'])):'DATE PENDING'))?></div><div class="title"><?=e($title)?></div><?php if(in_array($type,['winners','results'],true)):?><div class="podium"><?php foreach([4,2,1,3,5] as $rank):$x=null;foreach($items as $row){if((int)$row['final_rank']===$rank){$x=$row;break;}}?><div class="podium-slot"><?php if($x):?><div class="podium-person"><div class="podium-photos"><?php if(!empty($x['leader_photo'])):?><img src="<?=e($x['leader_photo'])?>" onerror="this.remove()"><?php endif;?><?php if(!empty($x['follower_photo'])):?><img src="<?=e($x['follower_photo'])?>" onerror="this.remove()"><?php endif;?></div><div class="podium-name"><?=e($x['leader_name'])?><?=!empty($x['follower_name'])?' & '.e($x['follower_name']):''?></div><div class="podium-country"><?php $parts=[];if(!empty($x['leader_country']))$parts[]=CountryFlagService::emoji($x['leader_country']).' '.$x['leader_country'];if(!empty($x['follower_country'])&&$x['follower_country']!==$x['leader_country'])$parts[]=CountryFlagService::emoji($x['follower_country']).' '.$x['follower_country'];echo e(implode(' · ',$parts));?></div></div><div class="block p<?=$rank?>"><?=$rank?></div><?php endif;?></div><?php endforeach;?></div><?php else:?><div class="list"><?php if($type==='scoring'):$x=$items[0];?><div class="item"><div class="big"><?=(int)($x['submitted']??0)?> / <?=(int)($x['total']??0)?></div><div class="small">JUDGES SUBMITTED</div></div><?php elseif($type==='judges'):foreach($items as $x):$country=$x['country']??'';?><div class="item"><?php if(!empty($x['photo_url'])):?><img class="photo" src="<?=e($x['photo_url'])?>" onerror="this.remove()"><?php endif;?><div class="name"><?=e($x['full_name']?:$x['judge_name'])?><?=(int)$x['is_chief']?' ★':''?></div><?php if($country):?><div class="small"><?=e(CountryFlagService::emoji($x['country_code']?:$country))?> <?=e($country)?></div><?php endif;?></div><?php endforeach;else:foreach($items as $x):$animalPhoto=$animalPlaceholders[abs((int)crc32((string)(($x['bib_number']??'').'|'.($x['display_name']??''))))%count($animalPlaceholders)];$photoUrl=!empty($x['photo_url'])?(string)$x['photo_url']:$animalPhoto;?><div class="item"><img class="photo" src="<?=e($photoUrl)?>" onerror="this.onerror=null;this.src='<?=e($animalPhoto)?>'"><div class="name"><?=e($x['display_name'])?></div><div class="small"><?=!empty($x['bib_number'])?'BIB '.(int)$x['bib_number']:'BIB UNASSIGNED'?><?php if(!empty($x['country'])):?> · <?=e(CountryFlagService::emoji($x['country']))?> <?=e($x['country'])?><?php endif;?></div></div><?php endforeach;endif;?></div><?php endif;?></div></div></body></html>
